  static Texture2D Load(string key){if(!pictures.TryGetValue(key,out var t)){t=Resources.Load<Texture2D>(key);pictures[key]=t;}return t;}
  internal static RenderTexture Backdrop(Texture source){if(blurred.TryGetValue(source,out var rt))return rt;if(blur==null){var shader=Resources.Load<Shader>("Shaders/LoadingBlur");if(shader==null)return null;blur=new Material(shader);}int w=512,h=Mathf.Max(1,Mathf.RoundToInt(w*source.height/(float)source.width));rt=new RenderTexture(w,h,0,RenderTextureFormat.ARGB32){name="동일 원본 로딩 블러",filterMode=FilterMode.Bilinear,wrapMode=TextureWrapMode.Clamp};rt.Create();var previous=RenderTexture.active;try{Graphics.Blit(source,rt,blur);}finally{RenderTexture.active=previous;}blurred[source]=rt;return rt;}
