   GUI.matrix=NativeUiViewport.EdgeMatrix;var a=NativeUiViewport.Edges;var art=new Rect(0,0,a.Width,1080);GUI.color=new Color(0,0,0,color.a*alpha);NativeUiAudit.DrawTexture(art,Texture2D.whiteTexture);bool expanded=false;Texture t=gate?Resources.Load<Texture2D>("Art/lobby/logo_exoduser_solid"):Picture(ForcedImage>=1?ForcedImage:index,out expanded);
   if(t!=null){if(!gate&&!expanded){var bg=Backdrop(t);GUI.color=new Color(.28f,.28f,.28f,color.a*alpha);NativeUiAudit.DrawTexture(art,bg!=null?(Texture)bg:t,ScaleMode.ScaleAndCrop,false);}GUI.color=new Color(1,1,1,color.a*alpha);var box=gate?new Rect(art.center.x-400,art.center.y-220,800,440):art;var front=Contain(box,t);if(expanded){float cover=Mathf.Max(box.width/t.width,box.height/t.height);front=new Rect(box.center.x-t.width*cover/2,box.center.y-t.height*cover/2,t.width*cover,t.height*cover);}NativeUiAudit.DrawTexture(expanded?box:front,t,expanded?ScaleMode.ScaleAndCrop:ScaleMode.StretchToFill,true);NativeUiAudit.Region(art,"component","loading-art","전체 화면 원화");NativeUiAudit.Region(front,"component","loading-source-canvas","mode="+(expanded?"expanded":gate?"gate":"fallback")+":"+t.name+":"+t.width+"x"+t.height);}
   float statusH=Mathf.Clamp(Screen.height*.22f,150,300)/a.Scale,statusY=1080-statusH;var status=new Rect(0,statusY,a.Width,statusH);if(overlay==null)overlay=NativeSilverHellUi.Effect(1,256,(u,v)=>new Color(5/255f,5/255f,6/255f,v<.35f?Mathf.Lerp(0,.32f,v/.35f):Mathf.Lerp(.32f,.78f,(v-.35f)/.65f)));GUI.color=new Color(1,1,1,color.a*alpha);NativeUiAudit.DrawTexture(status,overlay,ScaleMode.StretchToFill,true);float maxW=Mathf.Min(Screen.width*.88f,Screen.height*1.5f)/a.Scale;var font=NativeSilverHellUi.TextFont(NativeSilverHellUi.Font(true),title);var st=new GUIStyle(GUI.skin.label){font=font,fontSize=Mathf.RoundToInt(Mathf.Clamp(Screen.height*.021f,16,26)/a.Scale),fontStyle=FontStyle.Normal,alignment=TextAnchor.MiddleCenter,wordWrap=false,padding=new RectOffset(),margin=new RectOffset()};st.normal.textColor=new Color(230/255f,223/255f,206/255f);float titleH=st.fontSize*1.5f,detailSize=Mathf.RoundToInt(Mathf.Clamp(Screen.height*.0135f,11,17)/a.Scale),detailH=string.IsNullOrEmpty(detail)?0:detailSize*1.4f,bottomPad=(gate?Mathf.Clamp(Screen.height*.04f,24,56):Mathf.Clamp(Screen.height*.03f,18,44))/a.Scale,lineY=1080-bottomPad;float titleY=lineY-8/a.Scale-titleH-(detailH>0?detailH+8/a.Scale:0);var titleRect=new Rect((a.Width-maxW)/2,titleY,maxW,titleH);Spaced(titleRect,title,st,.12f,a.Scale);NativeUiAudit.Region(titleRect,"component","loading-title","하단 정렬/400/자간 .12em");if(detailH>0){st.font=NativeSilverHellUi.TextFont(NativeSilverHellUi.Font(true),detail);st.fontSize=Mathf.RoundToInt(detailSize);st.normal.textColor=new Color(192/255f,184/255f,166/255f);Spaced(new Rect(titleRect.x,titleRect.yMax+8/a.Scale,maxW,detailH),detail,st,.08f,a.Scale);} float lineW=Mathf.Min(Screen.height*.32f,Screen.width*.8f)/a.Scale,lineH=1/a.Scale;var line=new Rect((a.Width-lineW)/2,lineY,lineW,lineH);GUI.color=new Color(176/255f,145/255f,82/255f,color.a*alpha*.28f);NativeUiAudit.DrawTexture(line,Texture2D.whiteTexture);GUI.color=new Color(199/255f,167/255f,107/255f,color.a*alpha);NativeUiAudit.DrawTexture(new Rect(line.x,line.y,line.width*Mathf.Clamp01(progress),line.height),Texture2D.whiteTexture);NativeUiAudit.Region(status,"component","loading-status","그림 위 하단 그라데이션 오버레이");
  }finally{GUI.matrix=matrix;GUI.color=color;}}

 }
